GOAL: Fix a bug in /gin/response_writer.go.

BUG: `responseWriter.WriteHeader(code int)` currently updates the recorded status even when the response has already been sent:

    func (w *responseWriter) WriteHeader(code int) {
        if code > 0 && w.status != code {
            if w.Written() {
                debugPrint("[WARNING] Headers were already written. Wanted to override status code %d with %d", w.status, code)
            }
            w.status = code
        }
    }

So after `w.WriteHeader(http.StatusOK); w.WriteHeaderNow()` (response already sent, client got 200), a later `w.WriteHeader(http.StatusUnauthorized)` makes `w.Status()` report 401 even though 401 was never sent to the client. Expected: once the response has been written, the recorded status must not change (the warning is logged and the call is ignored).

FIX: add an early `return` in the already-written branch, i.e.:

    func (w *responseWriter) WriteHeader(code int) {
        if code > 0 && w.status != code {
            if w.Written() {
                debugPrint("[WARNING] Headers were already written. Wanted to override status code %d with %d", w.status, code)
                return
            }
            w.status = code
        }
    }

Change ONLY that function in /gin/response_writer.go. Do not touch anything else. Do NOT edit or delete any pre-existing *_test.go file.

VERIFICATION (run all of this yourself with bash):
1. Baseline: `cd /gin && go test ./... 2>&1 | tail -40` and record results.
2. Apply the edit.
3. `cd /gin && go test ./... 2>&1 | tail -40` — every package that passed at baseline must still pass. Report exact output.
4. Write a TEMPORARY test file /gin/zz_tmp_status_test.go (package gin) covering the reported scenario and run it:

package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestTmpStatusAfterWritten(t *testing.T) {
	testWriter := httptest.NewRecorder()
	writer := &responseWriter{}
	writer.reset(testWriter)
	w := ResponseWriter(writer)

	w.WriteHeader(http.StatusOK)
	w.WriteHeaderNow()
	if !w.Written() {
		t.Fatal("expected written")
	}
	w.WriteHeader(http.StatusUnauthorized)
	if got := w.Status(); got != http.StatusOK {
		t.Fatalf("Status() = %d, want %d", got, http.StatusOK)
	}
	if testWriter.Code != http.StatusOK {
		t.Fatalf("recorder code = %d, want 200", testWriter.Code)
	}

	// before the response is written, WriteHeader must still take effect
	w2 := ResponseWriter(&responseWriter{})
	r2 := httptest.NewRecorder()
	w2.(*responseWriter).reset(r2)
	w2.WriteHeader(http.StatusMultipleChoices)
	if got := w2.Status(); got != http.StatusMultipleChoices {
		t.Fatalf("Status() = %d, want 300", got)
	}
	w2.WriteHeaderNow()
	if r2.Code != http.StatusMultipleChoices {
		t.Fatalf("recorder code = %d, want 300", r2.Code)
	}
}

Run `cd /gin && go test -run TestTmpStatusAfterWritten -v . 2>&1 | tail -20`. Also confirm the test FAILS without the fix (temporarily revert, run, then re-apply the fix) to prove it exercises the bug. Then delete the temp file (`rm /gin/zz_tmp_status_test.go`) and confirm `git -C /gin status --porcelain` shows only ` M response_writer.go`.

REPORT: exact diff, baseline vs after test output, temp test output (with and without the fix), and git status.

