package gin

import (
	"net/http"
	"testing"
)

func tmpHandler(c *Context) {
	c.String(http.StatusOK, "%s|%s|%s", c.Param("name"), c.Params.ByName("last_name"), c.Param("wild"))
}

func TestTmpRuntimeRoute(t *testing.T) {
	// route registered AFTER the engine has served a request
	r := ginNewForTmp()
	w := PerformRequest(r, "GET", "/test/john/smith/is/super/great")
	if w.Code != http.StatusNotFound {
		t.Fatalf("expected 404 before registration, got %d", w.Code)
	}
	r.GET("/test/:name/:last_name/*wild", tmpHandler)
	w = PerformRequest(r, "GET", "/test/john/smith/is/super/great")
	if w.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", w.Code)
	}
	if body := w.Body.String(); body != "john|smith|is/super/great" {
		t.Errorf("runtime route: params wrong, got %q", body)
	}

	// same route registered before any request
	r2 := ginNewForTmp()
	r2.GET("/test/:name/:last_name/*wild", tmpHandler)
	w2 := PerformRequest(r2, "GET", "/test/john/smith/is/super/great")
	if w2.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d", w2.Code)
	}
	if body := w2.Body.String(); body != "john|smith|is/super/great" {
		t.Errorf("static route: params wrong, got %q", body)
	}
}

func ginNewForTmp() *Engine { return New() }
EOF
